import { createRuntime } from '@migaia/reactive'
import { sharedInt32 } from '@migaia/store-shared'

const runtime = createRuntime({ schedulerStrategy: (run) => run() })
const counter = sharedInt32(runtime, 5)
let runs = 0
const observer = runtime.effect(() => {
  runs++
  void counter.value
})
counter.value = 5
console.log(runs, counter.peek())
try {
  counter.value = 1.5
} catch (error) {
  console.log(error instanceof RangeError, (error as { code: string }).code)
}
console.log(counter.peek())
counter.value = 6
console.log(runs, counter.peek())
observer.dispose()
counter.dispose()

import { createRuntime } from '@migaia/reactive'
import { SharedInt32Array } from '@migaia/store-shared'

const values = new SharedInt32Array(createRuntime(), 1, { initialValues: [7] })
const original = new TypeError('invalid increment')
try {
  values.update(0, () => {
    throw original
  })
} catch (error) {
  console.log(error === original, error instanceof TypeError, (error as { code: string }).code)
}
console.log(values.get(0))
console.log(values.update(0, (current) => current + 1))
values.dispose()

const buffer = new SharedArrayBuffer(Int32Array.BYTES_PER_ELEMENT)
const value = new Int32Array(buffer)
const before = Atomics.load(value, 0)
Atomics.store(value, 0, before + 1) // Pitfall: separate reads and writes lose increments between competing writers.
const copy = new Int32Array(buffer) // Pitfall: another view aliases the same bytes; it is not an independent snapshot.
const latest = Atomics.load(value, 0) // Pitfall: reading new bytes does not publish them to the receiving reactive graph.
void copy
void latest

